import{_ as o,C as m,o as c,c as h,j as s,a as l,E as t,a2 as n,w as p}from"./chunks/framework.B-bxTAy7.js";const f=JSON.parse('{"title":"实验台与安全 · 器材清单与排查顺序","description":"搭建实验台的完整方案：三个预算档位的器材清单、强电与弱电的分区方式、保险丝与限流的选法、电容放电的科学步骤、静电防护、接地与漏电保护，以及出问题时的断电排查顺序。","frontmatter":{"title":"实验台与安全 · 器材清单与排查顺序","description":"搭建实验台的完整方案：三个预算档位的器材清单、强电与弱电的分区方式、保险丝与限流的选法、电容放电的科学步骤、静电防护、接地与漏电保护，以及出问题时的断电排查顺序。","outline":[2,3]},"headers":[],"relativePath":"lab/bench.md","filePath":"lab/bench.md","lastUpdated":1792603101000}'),g={name:"lab/bench.md"},d={class:"tip custom-block"};function x(y,a,v,u,b,k){const i=m("Meta"),r=m("Prereq"),e=m("FigBox");return c(),h("div",null,[a[10]||(a[10]=s("h1",{id:"实验台与安全",tabindex:"-1"},[l("实验台与安全 "),s("a",{class:"header-anchor",href:"#实验台与安全","aria-label":'Permalink to "实验台与安全"'},"​")],-1)),t(i,{time:"40 min",level:"核心",note:"安全不是小心一点，而是一串可以背下来的动作：分区、限流、放电、防静电、接地、先断后查"}),a[11]||(a[11]=s("p",null,[s("strong",null,"这一页要解决什么"),l("：实验台上的事故几乎都不是「不懂 220 V 危险」，而是流程缺了一步——没分区、没限流、没放电、没验证就伸手。这一页把台子的器材、电流边界、静电防护与出问题时的动作顺序串成一套可背下来的流程。读完你应该能：按预算配齐一张台子、给电源设对限流、知道大电容断电后该怎么放、以及出事时第一步先做什么。")],-1)),s("div",d,[a[4]||(a[4]=s("p",{class:"custom-block-title"},"读这页之前",-1)),s("ul",null,[s("li",null,[a[0]||(a[0]=n('<strong>需要会</strong>：欧姆定律、功率 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>=</mo><mi>U</mi><mi>I</mi></mrow><annotation encoding="application/x-tex">P=UI</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span></span></span></span>（',4)),t(r,{id:"ohm"}),a[1]||(a[1]=l("）；电容储能与 RC 放电的时间常数（",-1)),t(r,{id:"time-constant"}),a[2]||(a[2]=l("）。",-1))]),a[3]||(a[3]=n('<li><strong>这一页用到的符号</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>τ</mi><mo>=</mo><mi>R</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">\\tau = RC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 是<strong>时间常数</strong>（时间常数的定义与 5τ 放尽见 <a href="./../ee/03-transient/three-factor">07 · 三要素法</a>）；<strong>漏保</strong>是漏电保护器的简称（residual current device，比较火线与零线电流之差、超过 30 mA 即切断的人身保护装置）；PE 指保护接地线（protective earth，三脚插头中间那根）。全部约定见<a href="./../guide/notation">符号与约定</a>。</li><li><strong>人身安全的物理原理</strong>（摆脱电流、30 mA 动作值的由来）在<a href="./../ee/07-control/safety">电工学 21 · 安全用电</a>，本页只讲操作。</li>',2))])]),a[12]||(a[12]=n('<p>「实验台」听上去像是一个器材清单，实际上它是一个<strong>流程设计</strong>：什么东西放在哪里、电流从哪条路进来、什么情况下会断开、出问题时手先伸向哪里。器材决定了能做什么，流程决定了做的时候会不会出事。</p><p>这一页讲三件事：<strong>台子上应该有什么</strong>（三个预算档位）、<strong>电流的边界怎么设</strong>（保险丝、限流、放电）、<strong>出问题时按什么顺序动作</strong>。人身安全的物理原理（摆脱电流、漏保的 30 mA 动作值、保护接地与接零的区别）在<a href="./../ee/07-control/safety">电工学 21 · 安全用电</a>里有完整推导，这一页只讲「在台子上怎么做到」。</p><h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ol><li><strong>桌面分两区：强电区与弱电区，物理上隔开。</strong> 强电区只有 220 V 插座、开关电源的输入端；所有表笔、杜邦线、示波器探头只在弱电区活动。</li><li><strong>任何进了电路的能量都必须经过保险丝或限流。</strong> 台式电源把限流设在预计电流的 1.2~1.5 倍；电池供电串一个额定电流最小的保险丝；USB 供电用带保险的模块。</li><li><strong>断电 ≠ 没电。</strong> 大电容（开关电源、功放、闪光灯）在断电后可能存有几十到几百伏。<strong>断电、等 30 秒、用 1 kΩ 电阻放电、万用表确认 5 V 以下</strong>，四步走完才能碰。</li><li><strong>储能算一遍再决定小心程度</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>C</mi><msup><mi>U</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">E = \\frac{1}{2}CU^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>。220 μF/24 V 只有 63 mJ，400 V 的 100 μF 有 <strong>8 J</strong>，后者足以让心脏停跳。</li><li><strong>静电的能量很小，但它是 MOS 栅极的杀手</strong>：人体静电可达 15 kV，用 150 pF 储 16.9 mJ，而击穿 MOS 栅氧化层只需要 1 μJ。</li><li><strong>接地必须是单一的、可验证的。</strong> 示波器的地线夹、烙铁头、外壳、插座地都是大地；它们之间只能有一个「地」，错误的连接本身就是短路路径。</li><li><strong>漏电保护器保护的是人，不是设备。</strong> 30 mA / 0.1 s 是人身防护的门槛；过载与短路要靠保险丝和空气开关。</li><li><strong>出问题的动作顺序是固定的：断电 → 等 → 放电 → 验证 → 检查 → 分析。</strong> 顺序错了，分析的对象就是带电的电路。</li></ol><h2 id="器材清单" tabindex="-1">器材清单 <a class="header-anchor" href="#器材清单" aria-label="Permalink to &quot;器材清单&quot;">​</a></h2><p>这一节按预算给三档配置。选择原则只有一条：<strong>先用熟手里的，再买下一台</strong>——顺序是万用表 → 带限流的电源 → 示波器 → 焊台。</p><h3 id="入门档-能做完第一次上手的-3-小时清单" tabindex="-1">入门档：能做完第一次上手的 3 小时清单 <a class="header-anchor" href="#入门档-能做完第一次上手的-3-小时清单" aria-label="Permalink to &quot;入门档：能做完第一次上手的 3 小时清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>器材</th><th>关键规格</th><th>参考价格（元）</th></tr></thead><tbody><tr><td>数字万用表</td><td>3½ 位或 4½ 位，自动量程，真有效值，带保险丝</td><td>120</td></tr><tr><td>简易示波器</td><td>USB 供电的便携式（带宽 10~50 MHz），或二手入门 DSO</td><td>400</td></tr><tr><td>电源</td><td>USB 转 5 V / 3.3 V 模块，带保险</td><td>40</td></tr><tr><td>面包板 + 杜邦线</td><td>830 孔面包板一块，公对公 / 母对母各 30 根</td><td>50</td></tr><tr><td>焊接套装</td><td>恒温烙铁台（60 W）、焊锡丝 0.8 mm、助焊剂笔、吸锡带、镊子</td><td>150</td></tr><tr><td>工具与杂物</td><td>斜口钳、剥线钳、小板手、防静电手环、万用表表笔</td><td>100</td></tr><tr><td><strong>合计</strong></td><td></td><td><strong>860</strong></td></tr></tbody></table><h3 id="进阶档-能独立做电源、运放、mcu-调试" tabindex="-1">进阶档：能独立做电源、运放、MCU 调试 <a class="header-anchor" href="#进阶档-能独立做电源、运放、mcu-调试" aria-label="Permalink to &quot;进阶档：能独立做电源、运放、MCU 调试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>器材</th><th>关键规格</th><th>参考价格（元）</th></tr></thead><tbody><tr><td>台式万用表</td><td>4½ 位，真有效值，带四线电阻档</td><td>300</td></tr><tr><td>数字示波器</td><td>100 MHz / 1 GSa/s，两通道，带 10X 探头</td><td>1200</td></tr><tr><td>直流可调电源</td><td>双路，30 V / 3 A，恒压恒流，带限流显示</td><td>500</td></tr><tr><td>函数发生器</td><td>正弦 / 方波 / 三角波，1 μHz~5 MHz</td><td>400</td></tr><tr><td>焊接与检修工具</td><td>恒温焊台 60~80 W、热风枪、放大镜、吸锡器</td><td>200</td></tr><tr><td><strong>合计</strong></td><td></td><td><strong>2600</strong></td></tr></tbody></table><h3 id="实验室级-做电源环路、高速数字、精密测量" tabindex="-1">实验室级：做电源环路、高速数字、精密测量 <a class="header-anchor" href="#实验室级-做电源环路、高速数字、精密测量" aria-label="Permalink to &quot;实验室级：做电源环路、高速数字、精密测量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>器材</th><th>关键规格</th><th>参考价格（元）</th></tr></thead><tbody><tr><td>六位半台表</td><td>分辨率 1 μV，用于校准与误差预算</td><td>2500</td></tr><tr><td>数字示波器</td><td>4 通道，200 MHz 以上，带差分探头</td><td>6000</td></tr><tr><td>可编程电源</td><td>双路，带序列输出与精确限流</td><td>1800</td></tr><tr><td>任意波形发生器</td><td>双通道，带调制</td><td>1500</td></tr><tr><td>恒温焊台与热风枪</td><td>可编程温度曲线</td><td>900</td></tr><tr><td><strong>合计</strong></td><td></td><td><strong>12700</strong></td></tr></tbody></table><blockquote><p><strong>预算有限时先买什么</strong>：万用表 → 电源（带限流）→ 示波器 → 烙铁。<strong>示波器之前，先把万用表用熟</strong>；一台 100 MHz 的示波器加上不会用，比一台会用的小示波器贡献更少。</p></blockquote><h3 id="不推荐购买的东西" tabindex="-1">不推荐购买的东西 <a class="header-anchor" href="#不推荐购买的东西" aria-label="Permalink to &quot;不推荐购买的东西&quot;">​</a></h3><ul><li><strong>不带限流的「实验电源」</strong>（只有电压调节旋钮）：它等于一台随时可以短路的电源；</li><li><strong>便宜的 220 V 隔离变压器</strong>（没有地线、没有保险）：很多人以为它是安全工具，实际上它取消了保护地，用得不对更危险；</li><li><strong>五合一测试笔、万能电源适配器</strong>：输出电压由跳线选择，极易误设。</li></ul><h2 id="强电与弱电分区" tabindex="-1">强电与弱电分区 <a class="header-anchor" href="#强电与弱电分区" aria-label="Permalink to &quot;强电与弱电分区&quot;">​</a></h2><p>这一节是台子的物理布局：<strong>用一块绝缘垫把 220 V 与弱电隔成两个动作区域</strong>。布局画在图里，四条规则跟着图走。</p><h3 id="分区的意义" tabindex="-1">分区的意义 <a class="header-anchor" href="#分区的意义" aria-label="Permalink to &quot;分区的意义&quot;">​</a></h3><p>一个人同时处理 220 V 与 3.3 V 时，真正的风险不是「不知道 220 V 危险」，而是<strong>手在弱电区形成了习惯</strong>：随手把表笔往一个端子上戳、随手去摸一个发热的元件。当这个动作发生在有 220 V 的电路上，习惯就变成了事故。</p><p>分区就是<strong>用物理边界，把危险区的动作方式与安全区隔开</strong>。</p><h3 id="分区怎么做" tabindex="-1">分区怎么做 <a class="header-anchor" href="#分区怎么做" aria-label="Permalink to &quot;分区怎么做&quot;">​</a></h3>',21)),t(e,{title:"实验台分区图：绝缘垫是强电与弱电的物理边界",kind:"结构",note:"上半：强电区只有墙面插座、开关电源输入端与（可选的）隔离变压器，220 V 的线不跨过绝缘垫。下半：弱电区是台面主体，台式电源、示波器、面包板都在这里；防静电台垫经 1 MΩ 接大地。所有表笔、杜邦线、探头的活动范围到绝缘垫为止。"},{default:p(()=>[...a[5]||(a[5]=[s("svg",{viewBox:"0 0 560 320",role:"img","aria-label":"实验台分区俯视图：上方强电区与下方弱电区由绝缘垫隔开，防静电台垫经 1 兆欧接地"},[s("g",{"font-size":"11",fill:"var(--vp-c-text-1)"},[s("rect",{x:"16",y:"16",width:"528",height:"92",rx:"8",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-brand-1)","stroke-width":"1.8"}),s("text",{x:"32",y:"36",fill:"var(--vp-c-brand-1)","font-weight":"700"},"强电区（220 V）"),s("rect",{x:"36",y:"48",width:"130",height:"46",rx:"6",fill:"none",stroke:"var(--vp-c-text-2)","stroke-width":"1.4"}),s("text",{x:"101",y:"68","text-anchor":"middle"},"墙面插座"),s("text",{x:"101",y:"84","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"三孔 · 带漏保"),s("line",{x1:"166",y1:"71",x2:"206",y2:"71",stroke:"var(--vp-c-text-2)","stroke-width":"1.6"}),s("rect",{x:"206",y:"48",width:"130",height:"46",rx:"6",fill:"none",stroke:"var(--vp-c-text-2)","stroke-width":"1.4"}),s("text",{x:"271",y:"68","text-anchor":"middle"},"开关电源输入"),s("text",{x:"271",y:"84","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"220 V 只到这一端"),s("rect",{x:"356",y:"48",width:"130",height:"46",rx:"6",fill:"none",stroke:"var(--vp-c-text-3)","stroke-width":"1.4","stroke-dasharray":"5 3"}),s("text",{x:"421",y:"68","text-anchor":"middle"},"隔离变压器（可选）"),s("text",{x:"421",y:"84","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"隔离被测设备，不隔离示波器"),s("rect",{x:"16",y:"122",width:"528",height:"22",rx:"4",fill:"none",stroke:"var(--vp-c-text-2)","stroke-width":"1.4"}),s("text",{x:"280",y:"137","text-anchor":"middle",fill:"var(--vp-c-text-2)"},"绝缘垫 ≥ 2 mm —— 强电的线不跨过它"),s("rect",{x:"16",y:"158",width:"528",height:"146",rx:"8",fill:"none",stroke:"var(--vp-c-text-2)","stroke-width":"1.6"}),s("text",{x:"32",y:"178","font-weight":"700"},"弱电区（≤ 30 V）"),s("rect",{x:"36",y:"192",width:"120",height:"44",rx:"6",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-divider)"}),s("text",{x:"96",y:"210","text-anchor":"middle"},"台式电源"),s("text",{x:"96",y:"226","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"限流已设"),s("rect",{x:"176",y:"192",width:"120",height:"44",rx:"6",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-divider)"}),s("text",{x:"236",y:"210","text-anchor":"middle"},"示波器"),s("text",{x:"236",y:"226","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"探头只在左侧活动"),s("rect",{x:"316",y:"192",width:"110",height:"44",rx:"6",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-divider)"}),s("text",{x:"371",y:"210","text-anchor":"middle"},"面包板 / 洞洞板"),s("text",{x:"371",y:"226","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"被调电路"),s("rect",{x:"446",y:"192",width:"86",height:"44",rx:"6",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-divider)"}),s("text",{x:"489",y:"210","text-anchor":"middle"},"防静电台垫"),s("text",{x:"489",y:"226","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"经 1 MΩ 接地"),s("text",{x:"280",y:"272","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"规则：弱电区没有一根线直接通到 220 V；末端必须经过电源模块或隔离"),s("text",{x:"280",y:"290","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"手伸进强电区之前停一下：确认手上没有表笔、没有金属")])],-1)])]),_:1}),a[13]||(a[13]=n('<p>具体规则：</p><ol><li>强电区的线<strong>不跨越绝缘垫</strong>，只能用插座或插排进入；</li><li>弱电区的所有连线，末端在强电区之前<strong>必须经过一个电源模块或隔离</strong>，也就是说，弱电区没有一根线直接通到 220 V；</li><li>桌面（至少在弱电区）铺一块<strong>防静电台垫</strong>，台垫通过 1 MΩ 电阻接到大地（不是直接接大地，那样会让人在接触漏电时变成良好导体）；</li><li>手在进入危险区前<strong>必须停一下</strong>，确认手上没有表笔、没有金属，动作之前默念一遍「这一段有没有电」。</li></ol><h3 id="什么时候必须用隔离变压器" tabindex="-1">什么时候必须用隔离变压器 <a class="header-anchor" href="#什么时候必须用隔离变压器" aria-label="Permalink to &quot;什么时候必须用隔离变压器&quot;">​</a></h3><p>需要把<strong>被测设备</strong>与市电隔离时（例如触摸式调光器、开关电源输入端的调试）。做法是：把<strong>被测设备</strong>接在隔离变压器的输出端，而不是把示波器接在隔离变压器的输出端。</p><blockquote><p><strong>为什么不能隔离示波器</strong>：示波器的 BNC 外壳与三脚插头的 PE 相连，隔离变压器会让示波器<strong>失去保护地</strong>。一旦探头地线与内部短路，外壳就可能带 220 V，而你没有意识到。隔离被测设备，保证了示波器的地与大地仍然相连，而设备的「地」与大地断开。</p></blockquote><h2 id="保险丝与限流" tabindex="-1">保险丝与限流 <a class="header-anchor" href="#保险丝与限流" aria-label="Permalink to &quot;保险丝与限流&quot;">​</a></h2><p>这一节给台上的每一条电流通路设边界：<strong>保险丝保护「持续过载」，限流保护「接反与短路」</strong>，两者的选法与设置顺序各有一张图或一个口诀。</p><h3 id="保险丝不是「防止烧东西」-是「有界限地烧」" tabindex="-1">保险丝不是「防止烧东西」，是「有界限地烧」 <a class="header-anchor" href="#保险丝不是「防止烧东西」-是「有界限地烧」" aria-label="Permalink to &quot;保险丝不是「防止烧东西」，是「有界限地烧」&quot;">​</a></h3><p>保险丝的额定电流是<strong>它在这个电流下能长时间通过而不熔断</strong>的值。真正的熔断特性是：</p><table tabindex="0"><thead><tr><th>电流倍数</th><th>典型熔断时间</th></tr></thead><tbody><tr><td>1.5 倍</td><td>数小时（慢断型）/ 数分钟</td></tr><tr><td>2 倍</td><td>几十秒到数分钟（随型号而定，差异极大）</td></tr><tr><td>5 倍</td><td>几秒</td></tr><tr><td>10 倍以上</td><td>毫秒级</td></tr></tbody></table><p><strong>所以保险丝保护的是「持续过载」与「大电流短路」，而不是「微弱过载」。</strong> 一个 1 A 的保险丝，在 1.5 A 下可能几小时都不熔断，而一个 22 AWG 的线（0.3 mm²）在 1.5 A 下温升已经可观。</p><h3 id="选择保险丝的顺序" tabindex="-1">选择保险丝的顺序 <a class="header-anchor" href="#选择保险丝的顺序" aria-label="Permalink to &quot;选择保险丝的顺序&quot;">​</a></h3><ol><li><strong>先看供电能力</strong>：电池的保护板电流、USB 口的 500 mA~3 A 限制、电源的限流设定；</li><li><strong>再看线径</strong>：AWG 24 约 0.2 mm² 截面、电阻 0.085 Ω/m，适合 0.5~1 A；AWG 22 约 0.33 mm²，适合 1~2 A；</li><li><strong>再看负载额定</strong>：选额定电流的 1.5~2 倍；</li><li><strong>最后选类型</strong>：普通玻璃管保险丝反应快；慢熔型（T 型）适合电机、电容启动；自恢复保险丝（PTC）适合低电压场合，但动作后电阻很大，压降会很明显。</li></ol><h3 id="台式电源的限流" tabindex="-1">台式电源的限流 <a class="header-anchor" href="#台式电源的限流" aria-label="Permalink to &quot;台式电源的限流&quot;">​</a></h3><p>限流设置在<strong>预计电流的 1.2~1.5 倍</strong>。整个动作的思路是「让电源先学会多大力气，再去推电路」，五步顺序：</p>',15)),t(e,{title:"限流设置五步：短路定标 → 撤短接 → 设电压 → 接负载",kind:"结构",note:"前三步在输出关闭或短接状态下标定限流值，第四步才设目标电压，第五步接负载上电。这样任何接反、短路、装错都表现为电源停在 CC 模式（恒流），而不是把功率灌进电路。"},{default:p(()=>[...a[6]||(a[6]=[s("svg",{viewBox:"0 0 560 180",role:"img","aria-label":"限流设置五步流程：关输出调零、限流调到最低、短接输出标定、设电压、接负载上电"},[s("defs",null,[s("marker",{id:"bn-l1",viewBox:"0 0 10 10",refX:"8",refY:"5",markerWidth:"6",markerHeight:"6",orient:"auto"},[s("path",{d:"M 0 0 L 10 5 L 0 10 z",fill:"var(--vp-c-brand-1)"})])]),s("g",{"font-size":"11",fill:"var(--vp-c-text-1)"},[s("rect",{x:"16",y:"40",width:"92",height:"56",rx:"7",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-brand-1)","stroke-width":"1.4"}),s("text",{x:"62",y:"62","text-anchor":"middle"},"1 关输出"),s("text",{x:"62",y:"80","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"电压调到 0"),s("line",{x1:"108",y1:"68",x2:"130",y2:"68",stroke:"var(--vp-c-text-3)","stroke-width":"1.2","marker-end":"url(#bn-l1)"}),s("rect",{x:"132",y:"40",width:"92",height:"56",rx:"7",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-brand-1)","stroke-width":"1.4"}),s("text",{x:"178",y:"62","text-anchor":"middle"},"2 限流调最低"),s("text",{x:"178",y:"80","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"旋钮到最左"),s("line",{x1:"224",y1:"68",x2:"246",y2:"68",stroke:"var(--vp-c-text-3)","stroke-width":"1.2","marker-end":"url(#bn-l1)"}),s("rect",{x:"248",y:"40",width:"92",height:"56",rx:"7",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-brand-1)","stroke-width":"1.4"}),s("text",{x:"294",y:"62","text-anchor":"middle"},"3 短接输出"),s("text",{x:"294",y:"80","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"标定限流值"),s("line",{x1:"340",y1:"68",x2:"362",y2:"68",stroke:"var(--vp-c-text-3)","stroke-width":"1.2","marker-end":"url(#bn-l1)"}),s("rect",{x:"364",y:"40",width:"80",height:"56",rx:"7",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-text-2)","stroke-width":"1.4"}),s("text",{x:"404",y:"62","text-anchor":"middle"},"4 撤短接"),s("text",{x:"404",y:"80","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"设目标电压"),s("line",{x1:"444",y1:"68",x2:"466",y2:"68",stroke:"var(--vp-c-text-3)","stroke-width":"1.2","marker-end":"url(#bn-l1)"}),s("rect",{x:"468",y:"40",width:"76",height:"56",rx:"7",fill:"none",stroke:"var(--vp-c-text-2)","stroke-width":"1.4"}),s("text",{x:"506",y:"62","text-anchor":"middle"},"5 接负载"),s("text",{x:"506",y:"80","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"上电"),s("text",{x:"280",y:"140","text-anchor":"middle",fill:"var(--vp-c-text-2)"},"限流取「峰值电流 × 1.2」：太紧会误伤正常瞬态，太松短路时烧的是板子"),s("text",{x:"280",y:"162","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"上电后一切异常都应表现为 CC 灯亮 + 电压被拉低，这正是限流在保护电路")])],-1)])]),_:1}),a[14]||(a[14]=n('<p>这样做的目的是让电源<strong>先学会「多大力气」，再去推电路</strong>。接反、短路、元件装错，都只会让电源停在 CC 模式，而不是把功率灌进元件里。</p><h3 id="限流不是万能的" tabindex="-1">限流不是万能的 <a class="header-anchor" href="#限流不是万能的" aria-label="Permalink to &quot;限流不是万能的&quot;">​</a></h3><p><strong>限流设大了就没意义，设小了会误伤。</strong> 一台 5 V 电源限流 100 mA，接一个正常电流 80 mA 的负载，轻载时没问题，但一进入瞬态就会「触发 CC」，电压被拉下来，电路死机。这时应该限流 150 mA，而不是 100 mA 或 1 A。</p><h2 id="电容放电" tabindex="-1">电容放电 <a class="header-anchor" href="#电容放电" aria-label="Permalink to &quot;电容放电&quot;">​</a></h2><p>这一节处理「断电 ≠ 没电」：<strong>大电容在插头拔掉之后仍然储能，最多可达数焦耳</strong>。先算能量决定小心程度，再按四步放掉。</p><h3 id="先算一遍能量" tabindex="-1">先算一遍能量 <a class="header-anchor" href="#先算一遍能量" aria-label="Permalink to &quot;先算一遍能量&quot;">​</a></h3><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>C</mi><msup><mi>U</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">E = \\frac{1}{2}CU^2 </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">2</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span></span><table tabindex="0"><thead><tr><th>电容</th><th>电压</th><th>储能</th><th>危险程度</th></tr></thead><tbody><tr><td>220 μF</td><td>24 V</td><td>63 mJ</td><td>低压电路，放电即可</td></tr><tr><td>4700 μF</td><td>12 V</td><td>338 mJ</td><td>触碰有明显的「打火」感</td></tr><tr><td>1000 μF</td><td>50 V</td><td>1.25 J</td><td><strong>可能致命</strong>（远超安全阈值）</td></tr><tr><td>100 μF</td><td>400 V</td><td><strong>8.0 J</strong></td><td><strong>开关电源输入电容，必须放电</strong></td></tr></tbody></table><p>人体的心室颤动阈值大致在几十毫焦的量级，所以 <strong>1 J 以上的储能是必须认真对待的</strong>。400 V / 100 μF 的输入电容，在拔掉插头的瞬间，储能是 8 J。</p><h3 id="放电的四步" tabindex="-1">放电的四步 <a class="header-anchor" href="#放电的四步" aria-label="Permalink to &quot;放电的四步&quot;">​</a></h3><ol><li><strong>断电</strong>：拔插头，不只是关开关。很多开关是单刀的，零线仍然连着；</li><li><strong>等 30 秒</strong>：让电源内部的泄放电阻起一点作用（有的有，有的没有）；</li><li><strong>放电</strong>：用一只 1 kΩ 到 10 kΩ、功率够的电阻跨接在电容两端，持续时间见下表；手不要碰电阻的两端；</li><li><strong>验证</strong>：用万用表直流档测电容两端，<strong>5 V 以下才算安全</strong>。</li></ol>',11)),t(e,{title:"放电四步：断电 → 等 → 放 → 验证，一步都不能省",kind:"结构",note:"第 1 步拔插头（开关可能是单刀的，零线仍带电）；第 2 步等 30 s 让内部泄放电阻工作；第 3 步用 1~10 kΩ 功率够的电阻跨接放电，手不碰电阻两端；第 4 步万用表直流档确认 5 V 以下。顺序错了，后面的动作就发生在带电的板子上。"},{default:p(()=>[...a[7]||(a[7]=[s("svg",{viewBox:"0 0 560 170",role:"img","aria-label":"放电四步流程：拔插头、等 30 秒、电阻放电、万用表验证 5 伏以下"},[s("defs",null,[s("marker",{id:"bn-d1",viewBox:"0 0 10 10",refX:"8",refY:"5",markerWidth:"6",markerHeight:"6",orient:"auto"},[s("path",{d:"M 0 0 L 10 5 L 0 10 z",fill:"var(--vp-c-brand-1)"})])]),s("g",{"font-size":"11",fill:"var(--vp-c-text-1)"},[s("rect",{x:"16",y:"34",width:"112",height:"56",rx:"7",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-brand-1)","stroke-width":"1.4"}),s("text",{x:"72",y:"56","text-anchor":"middle"},"1 断电：拔插头"),s("text",{x:"72",y:"74","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"不是关开关"),s("line",{x1:"128",y1:"62",x2:"150",y2:"62",stroke:"var(--vp-c-text-3)","stroke-width":"1.2","marker-end":"url(#bn-d1)"}),s("rect",{x:"152",y:"34",width:"100",height:"56",rx:"7",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-brand-1)","stroke-width":"1.4"}),s("text",{x:"202",y:"56","text-anchor":"middle"},"2 等 30 s"),s("text",{x:"202",y:"74","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"内部泄放起效"),s("line",{x1:"252",y1:"62",x2:"274",y2:"62",stroke:"var(--vp-c-text-3)","stroke-width":"1.2","marker-end":"url(#bn-d1)"}),s("rect",{x:"276",y:"34",width:"128",height:"56",rx:"7",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-brand-1)","stroke-width":"1.4"}),s("text",{x:"340",y:"56","text-anchor":"middle"},"3 电阻放电"),s("text",{x:"340",y:"74","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"1~10 kΩ · 手不碰两端"),s("line",{x1:"404",y1:"62",x2:"426",y2:"62",stroke:"var(--vp-c-text-3)","stroke-width":"1.2","marker-end":"url(#bn-d1)"}),s("rect",{x:"428",y:"34",width:"116",height:"56",rx:"7",fill:"none",stroke:"var(--vp-c-text-2)","stroke-width":"1.4"}),s("text",{x:"486",y:"56","text-anchor":"middle"},"4 验证 < 5 V"),s("text",{x:"486",y:"74","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"万用表直流档"),s("text",{x:"280",y:"130","text-anchor":"middle",fill:"var(--vp-c-text-2)"},"放电电阻按 U₀²/R < 额定功率选：400 V 用 1 kΩ 瞬间 160 W，电阻当场烧掉"),s("text",{x:"280",y:"152","text-anchor":"middle",fill:"var(--vp-c-text-3)"},"高压电容换 10 kΩ / 10 W，靠延长等待时间补偿；串联电容组要逐个放")])],-1)])]),_:1}),a[15]||(a[15]=n('<p>放电电阻的选择有个坑：<strong>用小阻值（如 10 Ω）放电会瞬间产生很大的脉冲电流，可能损坏电容本身，或者烧掉电阻</strong>。1 kΩ 在 400 V 上的瞬间功率是 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>400</mn><mn>2</mn></msup><mi mathvariant="normal">/</mi><mn>1000</mn><mo>=</mo><mn>160</mn></mrow><annotation encoding="application/x-tex">400^2/1000 = 160</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">40</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord">/1000</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">160</span></span></span></span> W，即使是 5 W 的电阻也会在一两秒内烧毁；换成 10 kΩ 时瞬间功率降到 16 W，用 10 W 的电阻就能安全工作。所以高压电容要先看电压再选电阻：<strong>电阻的两端电压平方除以阻值，必须小于它的额定功率</strong>。</p><h3 id="放电需要多久" tabindex="-1">放电需要多久 <a class="header-anchor" href="#放电需要多久" aria-label="Permalink to &quot;放电需要多久&quot;">​</a></h3><p>用 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi></mrow><annotation encoding="application/x-tex">R</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 放电的电容，电压按 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>u</mi><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mo>=</mo><msub><mi>U</mi><mn>0</mn></msub><msup><mi>e</mi><mrow><mo>−</mo><mi>t</mi><mi mathvariant="normal">/</mi><mi>R</mi><mi>C</mi></mrow></msup></mrow><annotation encoding="application/x-tex">u(t) = U_0 e^{-t/RC}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">u</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.038em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mathnormal mtight">t</span><span class="mord mtight">/</span><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span></span></span></span></span></span></span></span></span></span></span></span> 衰减。5 倍时间常数后剩下 0.7%。</p><table tabindex="0"><thead><tr><th>电容</th><th>电压</th><th>放电电阻</th><th>时间常数 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>τ</mi></mrow><annotation encoding="application/x-tex">\\tau</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span></th><th>5τ 后剩余</th></tr></thead><tbody><tr><td>1000 μF</td><td>50 V</td><td>1 kΩ</td><td>1.0 s</td><td>0.34 V</td></tr><tr><td>100 μF</td><td>400 V</td><td>1 kΩ</td><td>0.1 s</td><td>2.7 V（但瞬间功率 160 W，不可用）</td></tr><tr><td>4700 μF</td><td>12 V</td><td>1 kΩ</td><td>4.70 s</td><td>0.08 V</td></tr><tr><td>100 μF</td><td>400 V</td><td>10 kΩ</td><td>1.0 s</td><td>2.7 V</td></tr></tbody></table><blockquote><p><strong>注意 400 V 那一行</strong>：5τ 后仍有 2.7 V，单看数值不大，但如果你测的是<strong>串联电容组</strong>，每只电容的电压可能不相等。高压电容组必须逐个电容放电，不能只放一端。</p></blockquote><h3 id="不需要放电的「假电容」" tabindex="-1">不需要放电的「假电容」 <a class="header-anchor" href="#不需要放电的「假电容」" aria-label="Permalink to &quot;不需要放电的「假电容」&quot;">​</a></h3><p>小于 1 μF 的电容（例如 0.1 μF 的去耦电容），存储的能量也不小。一只拿 400 V 的 0.1 μF 通过 1 kΩ 的亦不会「安全」：峰值电流 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>400</mn><mi mathvariant="normal">/</mi><mn>1000</mn><mo>=</mo><mn>0.4</mn></mrow><annotation encoding="application/x-tex">400/1000 = 0.4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">400/1000</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4</span></span></span></span> A，虽然能量不足以致命，但手指会因不自觉的抽动而碰到脚下的硬物。</p><p>真正不需要放电的只有两种情况：一是<strong>低压小容量</strong>（例如 5 V 下的 0.1 μF，储能只有 1.25 μJ），二是<strong>电容两端已经被万用表验证在 5 V 以下</strong>。<strong>不确定就当它需要放电</strong>，判断的成本是几秒钟，不判断的成本可能是一次手术。</p><h2 id="静电" tabindex="-1">静电 <a class="header-anchor" href="#静电" aria-label="Permalink to &quot;静电&quot;">​</a></h2><p>这一节的反差最大：<strong>静电对人只是「啪」一下，对 MOS 栅极却是千倍以上的能量差</strong>。防护五件事全部围绕「让电荷慢慢走 1 MΩ 这条路」。</p><h3 id="人体静电有多大" tabindex="-1">人体静电有多大 <a class="header-anchor" href="#人体静电有多大" aria-label="Permalink to &quot;人体静电有多大&quot;">​</a></h3><p>冬天在化纤地毯上走几步，人体电压可以达到 <strong>15 kV</strong>，静电容量约 150 pF：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>C</mi><msup><mi>U</mi><mn>2</mn></msup><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>×</mo><mn>150</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>12</mn></mrow></msup><mo>×</mo><mo stretchy="false">(</mo><mn>15</mn><mo>×</mo><msup><mn>10</mn><mn>3</mn></msup><msup><mo stretchy="false">)</mo><mn>2</mn></msup><mo>=</mo><mn>16.9</mn><mtext> mJ</mtext></mrow><annotation encoding="application/x-tex">E = \\frac{1}{2}CU^2 = \\frac{1}{2} \\times 150\\times10^{-12} \\times (15\\times10^3)^2 = 16.9\\ \\text{mJ} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">2</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">2</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">150</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9474em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">12</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">15</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1141em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">3</span></span></span></span></span></span></span></span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">16.9</span><span class="mspace"> </span><span class="mord text"><span class="mord">mJ</span></span></span></span></span></span><p>放电瞬间的峰值电流（按 150 Ω 的人体阻抗）可达 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>15</mn><mtext> </mtext><mn>000</mn><mi mathvariant="normal">/</mi><mn>150</mn><mo>=</mo><mn>100</mn><mtext> A</mtext></mrow><annotation encoding="application/x-tex">15\\,000/150 = 100\\ \\text{A}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">15</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">000/150</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">100</span><span class="mspace"> </span><span class="mord text"><span class="mord">A</span></span></span></span></span>，持续时间几十纳秒。这个能量对人来说只是「啪」一下。</p><h3 id="但对-mos-器件来说是毁灭性的" tabindex="-1">但对 MOS 器件来说是毁灭性的 <a class="header-anchor" href="#但对-mos-器件来说是毁灭性的" aria-label="Permalink to &quot;但对 MOS 器件来说是毁灭性的&quot;">​</a></h3><p>现代 CMOS 的栅氧化层厚度只有几纳米，击穿电压约 20 V，栅电容 5 nF 时击穿所需的能量只有</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>×</mo><mn>5</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>9</mn></mrow></msup><mo>×</mo><msup><mn>20</mn><mn>2</mn></msup><mo>=</mo><mn>1.0</mn><mtext> </mtext><mi>μ</mi><mtext>J</mtext></mrow><annotation encoding="application/x-tex">E = \\frac{1}{2} \\times 5\\times10^{-9} \\times 20^2 = 1.0\\ \\mu\\text{J} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">2</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9474em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">9</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8641em;"></span><span class="mord">2</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">1.0</span><span class="mspace"> </span><span class="mord mathnormal">μ</span><span class="mord text"><span class="mord">J</span></span></span></span></span></span><p><strong>静电能量的千分之一就足以击穿栅极。</strong> 更隐蔽的是「软击穿」：栅极没有完全击穿，但漏电增大、阈值漂移，器件在几个月后失效。</p><h3 id="防静电的五件事" tabindex="-1">防静电的五件事 <a class="header-anchor" href="#防静电的五件事" aria-label="Permalink to &quot;防静电的五件事&quot;">​</a></h3><ol><li><strong>防静电手环</strong>：戴在手腕上，通过 1 MΩ 电阻接到大地。<strong>这个 1 MΩ 是安全设计</strong>，它让静电慢慢泄放，同时在你接触漏电时限制电流；</li><li><strong>防静电台垫</strong>：铺在桌面上，同样通过 1 MΩ 接地；</li><li><strong>拿芯片的姿势</strong>：拿两端、不拿引脚；不用的芯片放在导电泡沫或防静电袋里；</li><li><strong>先放电再接触</strong>：在碰板子之前，摸一下接地的金属外壳（如机箱、水管），让身上的电荷先跑掉；</li><li><strong>不要用塑料袋装芯片</strong>，尤其是冬天。</li></ol><h3 id="最容易忘的地方" tabindex="-1">最容易忘的地方 <a class="header-anchor" href="#最容易忘的地方" aria-label="Permalink to &quot;最容易忘的地方&quot;">​</a></h3><ul><li>示波器探头的尖端与外壳：探头带上静电后，接触被测电路的那一下就是放电；</li><li>USB 线的外壳：插拔时外壳先接触，但内部信号线可能先接触到静电；</li><li>面包板的金属弹簧片：你的手指第一次碰到它时就会放电，如果旁边有 MOS 管，就晚了。</li></ul><h2 id="接地与漏电保护" tabindex="-1">接地与漏电保护 <a class="header-anchor" href="#接地与漏电保护" aria-label="Permalink to &quot;接地与漏电保护&quot;">​</a></h2><p>这一节是台子的最后一条安全线：<strong>大地只有一个，接地的路径只能有一条</strong>；漏保管的是人，空开管的是设备，互不替代。</p><h3 id="单一接地点" tabindex="-1">单一接地点 <a class="header-anchor" href="#单一接地点" aria-label="Permalink to &quot;单一接地点&quot;">​</a></h3><p>你的台子上，以下东西在电气上都连到大地（PE）：</p><ul><li>示波器的 BNC 外壳与探头地线；</li><li>烙铁台的金属外壳（有些型号烙铁头也接地）；</li><li>万用表的表笔是绝缘的，不接大地；</li><li>台式电源的输出负极（<strong>通常悬空</strong>，这是好事）；</li><li>你的防静电手环 / 台垫（经 1 MΩ）。</li></ul><p><strong>「单一接地」的意思是</strong>：被测电路的参考地只能通过一个点接大地，其他地方不再连。如果你把电路的地接了示波器的地线夹，又接了烙铁头的地，又接了电源的地，就有了三条并联的接地路径，三条路之间的电位差会在你毫无察觉时造成电流：</p>',28)),t(e,{title:"台子上都谁接着大地，以及为什么只能留一条路",kind:"结构",note:"左侧列出接大地的设备：示波器 BNC 外壳、烙铁台金属壳、防静电台垫与手环（经 1 MΩ）；台式电源输出负极通常悬空（好事），万用表表笔绝缘不接地。右侧示意「多路径」的后果：两个接地点之间的电位差会沿你不知道的路径形成电流。"},{default:p(()=>[...a[8]||(a[8]=[s("svg",{viewBox:"0 0 560 260",role:"img","aria-label":"左栏设备接地清单，右栏多接地路径形成电位差电流的示意"},[s("defs",null,[s("marker",{id:"bn-g1",viewBox:"0 0 10 10",refX:"8",refY:"5",markerWidth:"6",markerHeight:"6",orient:"auto"},[s("path",{d:"M 0 0 L 10 5 L 0 10 z",fill:"var(--vp-c-text-3)"})])]),s("g",{"font-size":"11",fill:"var(--vp-c-text-1)"},[s("text",{x:"110",y:"18","text-anchor":"middle","font-weight":"700"},"台子上接大地的设备"),s("rect",{x:"20",y:"34",width:"190",height:"200",rx:"8",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-divider)"}),s("text",{x:"36",y:"58"},"· 示波器 BNC 外壳 + 探头地线"),s("text",{x:"36",y:"84"},"· 烙铁台金属外壳（部分头也接地）"),s("text",{x:"36",y:"110"},"· 防静电台垫 / 手环（经 1 MΩ）"),s("text",{x:"36",y:"136"},"· 台式电源输出负极：通常悬空（好）"),s("text",{x:"36",y:"162"},"· 万用表表笔：绝缘，不接大地"),s("text",{x:"36",y:"196",fill:"var(--vp-c-text-2)"},"手环直接接大地 = 接触漏电时"),s("text",{x:"36",y:"214",fill:"var(--vp-c-text-2)"},"变成低阻通路，反而更危险"),s("text",{x:"430",y:"18","text-anchor":"middle","font-weight":"700"},"多路径的后果"),s("rect",{x:"320",y:"60",width:"100",height:"40",rx:"6",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-divider)"}),s("text",{x:"370",y:"84","text-anchor":"middle"},"电路地"),s("line",{x1:"340",y1:"100",x2:"340",y2:"150",stroke:"var(--vp-c-text-3)","stroke-width":"1.4","marker-end":"url(#bn-g1)"}),s("text",{x:"332",y:"130","text-anchor":"end",fill:"var(--vp-c-text-3)"},"路 1：示波器地夹"),s("line",{x1:"400",y1:"100",x2:"400",y2:"150",stroke:"var(--vp-c-text-3)","stroke-width":"1.4","marker-end":"url(#bn-g1)"}),s("text",{x:"408",y:"130",fill:"var(--vp-c-text-3)"},"路 2：烙铁头地"),s("rect",{x:"320",y:"150",width:"100",height:"34",rx:"6",fill:"none",stroke:"var(--vp-c-text-2)","stroke-width":"1.4"}),s("text",{x:"370",y:"171","text-anchor":"middle"},"大地（PE）"),s("text",{x:"430",y:"210",fill:"var(--vp-c-text-2)"},"两路电阻不等 → 电位差沿"),s("text",{x:"430",y:"228",fill:"var(--vp-c-text-2)"},"你不知道的路径形成电流"),s("text",{x:"430",y:"246",fill:"var(--vp-c-text-3)"},"→ 只留一条接地点")])],-1)])]),_:1}),a[16]||(a[16]=n('<h3 id="漏电保护器" tabindex="-1">漏电保护器 <a class="header-anchor" href="#漏电保护器" aria-label="Permalink to &quot;漏电保护器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td>动作电流 30 mA</td><td>火线与零线电流之差超过 30 mA 时动作，用于人身防护</td></tr><tr><td>动作时间 0.1 s</td><td>在额定动作电流下的切断时间上限</td></tr><tr><td>与空气开关的区别</td><td>空气开关管过载与短路，漏保管漏电，<strong>两者不能互相替代</strong></td></tr></tbody></table><p>30 mA 这个值不是随便定的：在 220 V 下它对应的人体电阻约 7.3 kΩ，而大多数人洗澡后的皮肤电阻会降到这个量级以下。所以<strong>漏保的 30 mA 是在「多数人多数情况安全」与「正常设备漏电流不误动作」之间的折中</strong>。</p><h3 id="检查你的插座" tabindex="-1">检查你的插座 <a class="header-anchor" href="#检查你的插座" aria-label="Permalink to &quot;检查你的插座&quot;">​</a></h3><ol><li>墙壁插座必须是<strong>三孔</strong>的，中间的地脚是真实接地的（用验电笔或专用插座测试仪验证）；</li><li>插排上按一下漏保的 <strong>Test（测试）按钮</strong>，应该听到「咔」一声并断电；每月按一次；</li><li>千万不要用两孔插排、剪掉第三脚、或者把地线缠在暖气管上，最后这种做法看似「接地」，实际上引入了另一个电位点。</li></ol><h2 id="出问题时的排查顺序" tabindex="-1">出问题时的排查顺序 <a class="header-anchor" href="#出问题时的排查顺序" aria-label="Permalink to &quot;出问题时的排查顺序&quot;">​</a></h2><p>这一节是全页的收口：<strong>出事时的动作顺序是固定的</strong>。冒烟走「断电 → 放电 → 验证」，不冒烟走「验证工具 → 分段隔离」——顺序错了，分析对象就是带电的电路。</p><h3 id="冒烟、异响、发烫、焦味-立刻断电" tabindex="-1">冒烟、异响、发烫、焦味：立刻断电 <a class="header-anchor" href="#冒烟、异响、发烫、焦味-立刻断电" aria-label="Permalink to &quot;冒烟、异响、发烫、焦味：立刻断电&quot;">​</a></h3><p><strong>第一动作永远是断电</strong>，不是「看看是哪个元件冒烟」。顺序：</p>',9)),t(e,{title:"异常处置流程：冒烟走左边，不冒烟走右边",kind:"结构",note:"左：冒烟 / 焦味路线——拔电源 → 等 30 s → 电阻放电 → 万用表验证 5 V 以下 → 拔掉所有探头表笔 → 才开始看外观。右：不冒烟但不工作路线——先验证电源与工具，再断电测连接，最后限流上电分段隔离。两条路的共同点：先让电路确认没电，再让手靠近。"},{default:p(()=>[...a[9]||(a[9]=[s("svg",{viewBox:"0 0 560 280",role:"img","aria-label":"异常处置双路线流程图：左侧冒烟立即断电路线，右侧不冒烟验证排查路线"},[s("defs",null,[s("marker",{id:"bn-f1",viewBox:"0 0 10 10",refX:"8",refY:"5",markerWidth:"6",markerHeight:"6",orient:"auto"},[s("path",{d:"M 0 0 L 10 5 L 0 10 z",fill:"var(--vp-c-brand-1)"})]),s("marker",{id:"bn-f2",viewBox:"0 0 10 10",refX:"8",refY:"5",markerWidth:"6",markerHeight:"6",orient:"auto"},[s("path",{d:"M 0 0 L 10 5 L 0 10 z",fill:"var(--vp-c-text-3)"})])]),s("g",{"font-size":"11",fill:"var(--vp-c-text-1)"},[s("rect",{x:"16",y:"20",width:"240",height:"34",rx:"7",fill:"none",stroke:"var(--vp-c-brand-1)","stroke-width":"1.6"}),s("text",{x:"136",y:"41","text-anchor":"middle",fill:"var(--vp-c-brand-1)"},"冒烟 / 异响 / 焦味"),s("line",{x1:"136",y1:"54",x2:"136",y2:"70",stroke:"var(--vp-c-brand-1)","stroke-width":"1.2","marker-end":"url(#bn-f1)"}),s("rect",{x:"16",y:"72",width:"240",height:"150",rx:"8",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-divider)"}),s("text",{x:"32",y:"96"},"1. 拔被测电路电源（电源冒烟拔墙上插头）"),s("text",{x:"32",y:"122"},"2. 等 30 s"),s("text",{x:"32",y:"148"},"3. 放电电阻放掉大电容"),s("text",{x:"32",y:"174"},"4. 万用表电压档确认 5 V 以下"),s("text",{x:"32",y:"200"},"5. 拔掉探头 BNC 与所有表笔，再动板子"),s("line",{x1:"256",y1:"147",x2:"280",y2:"147",stroke:"var(--vp-c-brand-1)","stroke-width":"1.4","marker-end":"url(#bn-f1)"}),s("rect",{x:"282",y:"112",width:"120",height:"34",rx:"7",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-brand-1)","stroke-width":"1.4"}),s("text",{x:"342",y:"133","text-anchor":"middle",fill:"var(--vp-c-brand-1)"},"才开始看外观"),s("rect",{x:"304",y:"20",width:"240",height:"34",rx:"7",fill:"none",stroke:"var(--vp-c-text-2)","stroke-width":"1.6"}),s("text",{x:"424",y:"41","text-anchor":"middle"},"不冒烟但不工作"),s("line",{x1:"424",y1:"54",x2:"424",y2:"70",stroke:"var(--vp-c-text-3)","stroke-width":"1.2","marker-end":"url(#bn-f2)"}),s("rect",{x:"304",y:"72",width:"240",height:"150",rx:"8",fill:"var(--vp-c-bg-soft)",stroke:"var(--vp-c-divider)"}),s("text",{x:"320",y:"96"},"1. 验证电源：CC 灯亮 = 已进限流"),s("text",{x:"320",y:"122"},"2. 验证工具：拿电池确认表读数正常"),s("text",{x:"320",y:"148"},"3. 断电测电源对地电阻（几百欧以上）"),s("text",{x:"320",y:"174"},"4. 限流调小上电，看电流是否异常"),s("text",{x:"320",y:"200"},"5. 分段隔离：从电源往后一段一段接"),s("text",{x:"280",y:"252","text-anchor":"middle",fill:"var(--vp-c-text-2)"},"一上电就烧保险丝 = 一定有短路：先查短路，绝不换更大的保险丝再试")])],-1)])]),_:1}),a[17]||(a[17]=n('<ol><li>拔掉被测电路的电源（插头或电源输出），<strong>如果电源在冒烟，直接拔墙上的插头</strong>；</li><li>等 30 秒；</li><li>用放电电阻给大电容放电，放完后<strong>用万用表电压档</strong>（不是电流档、不是电阻档）确认电容两端 5 V 以下；</li><li>拔掉探头的 BNC 与所有表笔，再移动板子；</li><li>现在才开始检查：先看元件外观（烧黑的电阻、鼓包的电容、裂开的芯片），再看电路板背面。</li></ol><h3 id="不冒烟但电路不工作-先验证工具-再验证电路" tabindex="-1">不冒烟但电路不工作：先验证工具，再验证电路 <a class="header-anchor" href="#不冒烟但电路不工作-先验证工具-再验证电路" aria-label="Permalink to &quot;不冒烟但电路不工作：先验证工具，再验证电路&quot;">​</a></h3><ol><li><strong>验证电源</strong>：用万用表测输出端的实际电压，同时看电源面板：电压读数比设定值低，说明它已经进入限流（CC 指示灯亮），先把负载断开再试；</li><li><strong>验证测量工具</strong>：用另一个已知源（电池）确认万用表读数正常；</li><li><strong>断电测连接</strong>：电阻档测电源与地之间，正常应该几百欧以上（有电容时先小后大）；测关键节点的连通；</li><li><strong>限流下上电</strong>：把限流调小，观察电流是否异常大；</li><li><strong>分段隔离</strong>：从电源开始，一段一段往后接，每接一段测一次，直到找到出问题的段落。</li></ol><h3 id="一上电就烧保险丝-一定是短路" tabindex="-1">一上电就烧保险丝：一定是短路 <a class="header-anchor" href="#一上电就烧保险丝-一定是短路" aria-label="Permalink to &quot;一上电就烧保险丝：一定是短路&quot;">​</a></h3><p>不要换一个更大的保险丝再试。用电阻档测电源输入端与地之间，如果读数接近 0，短路就在这条线上；把负载一段段拆开，直到电阻恢复正常。</p><h3 id="什么时候可以「再看一眼」" tabindex="-1">什么时候可以「再看一眼」 <a class="header-anchor" href="#什么时候可以「再看一眼」" aria-label="Permalink to &quot;什么时候可以「再看一眼」&quot;">​</a></h3><p>只有在<strong>断电、放电、验证过</strong>之后，才允许「再看一眼是哪里的问题」。带电状态下用长表笔去戳冒烟的区域，是实验室最常见的手指、眼睛受伤原因。</p><h2 id="例题" tabindex="-1">例题 <a class="header-anchor" href="#例题" aria-label="Permalink to &quot;例题&quot;">​</a></h2><p>两道例题把安全参数算成数字：第一题算放电时间与电阻功率（对应「放电四步」），第二题算限流取值（对应「限流五步」）。</p><div class="tip custom-block" id="ex-bench-discharge"><p class="custom-block-title">例 1 · 一块 12 V 电源板，断电后多久才能碰</p><p><strong>题干</strong>：一块电源板输出端有 4700 μF 的电容，上电时电压 12 V。拔掉插头后，用 1 kΩ / 2 W 的电阻放电。求时间常数、放电到 5 V 所需时间、以及电阻在放电瞬间的功率是否超限。</p><p><strong>解</strong></p><p><strong>第 1 步：时间常数</strong></p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>τ</mi><mo>=</mo><mi>R</mi><mi>C</mi><mo>=</mo><mn>1000</mn><mo>×</mo><mn>4700</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>6</mn></mrow></msup><mo>=</mo><mn>4.70</mn><mtext> s</mtext></mrow><annotation encoding="application/x-tex">\\tau = RC = 1000 \\times 4700\\times10^{-6} = 4.70\\ \\text{s} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1000</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4700</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8641em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">6</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4.70</span><span class="mspace"> </span><span class="mord text"><span class="mord">s</span></span></span></span></span></span><p><strong>第 2 步：放电到 5 V 的时间</strong></p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>u</mi><mo stretchy="false">(</mo><mi>t</mi><mo stretchy="false">)</mo><mo>=</mo><mn>12</mn><msup><mi>e</mi><mrow><mo>−</mo><mi>t</mi><mi mathvariant="normal">/</mi><mi>τ</mi></mrow></msup><mo>=</mo><mn>5</mn><mtext>  </mtext><mo>⟹</mo><mtext>  </mtext><mi>t</mi><mo>=</mo><mi>τ</mi><mi>ln</mi><mo>⁡</mo><mfrac><mn>12</mn><mn>5</mn></mfrac><mo>=</mo><mn>4.70</mn><mo>×</mo><mn>0.875</mn><mo>=</mo><mn>4.11</mn><mtext> s</mtext></mrow><annotation encoding="application/x-tex">u(t) = 12 e^{-t/\\tau} = 5 \\implies t = \\tau \\ln\\frac{12}{5} = 4.70 \\times 0.875 = 4.11\\ \\text{s} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">u</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.938em;"></span><span class="mord">12</span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.938em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mathnormal mtight">t</span><span class="mord mtight">/</span><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6684em;vertical-align:-0.024em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⟹</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">ln</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">5</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">12</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4.70</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.875</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4.11</span><span class="mspace"> </span><span class="mord text"><span class="mord">s</span></span></span></span></span></span><p><strong>第 3 步：验证 5τ 后的剩余电压</strong></p><p>5τ = 23.5 s 后，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>u</mi><mo>=</mo><mn>12</mn><msup><mi>e</mi><mrow><mo>−</mo><mn>5</mn></mrow></msup><mo>=</mo><mn>0.081</mn></mrow><annotation encoding="application/x-tex">u = 12 e^{-5} = 0.081</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">u</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">12</span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.081</span></span></span></span> V，已经安全。</p><p><strong>第 4 步：电阻功率</strong></p><p>放电瞬间的功率 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>=</mo><msup><mi>U</mi><mn>2</mn></msup><mi mathvariant="normal">/</mi><mi>R</mi><mo>=</mo><msup><mn>12</mn><mn>2</mn></msup><mi mathvariant="normal">/</mi><mn>1000</mn><mo>=</mo><mn>0.144</mn><mtext> W</mtext></mrow><annotation encoding="application/x-tex">P = U^2/R = 12^2/1000 = 0.144\\ \\text{W}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord">/1000</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0.144</span><span class="mspace"> </span><span class="mord text"><span class="mord">W</span></span></span></span></span>，2 W 的电阻完全够。整个过程电阻承受的能量约 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>C</mi><msup><mi>U</mi><mn>2</mn></msup><mo>=</mo><mn>0.338</mn></mrow><annotation encoding="application/x-tex">\\frac{1}{2}CU^2 = 0.338</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.338</span></span></span></span> J，远小于 2 W × 4.7 s。</p><p><strong>结论</strong>：<strong>至少等 4~5 s 后万用表确认</strong>，保险起见等 10 s。这个电容组危险不大，但如果你把同样的 1 kΩ 电阻接在 400 V 的 100 μF 上，放电瞬间功率是 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>400</mn><mn>2</mn></msup><mi mathvariant="normal">/</mi><mn>1000</mn><mo>=</mo><mn>160</mn></mrow><annotation encoding="application/x-tex">400^2/1000 = 160</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">40</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord">/1000</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">160</span></span></span></span> W，<strong>1 kΩ 的电阻会当场烧掉</strong>，必须先用 10 kΩ / 10 W。</p><blockquote><p><strong>为什么这么想</strong> 放电电阻的选择要同时满足两个条件：<strong>电压降得够快</strong>（RC 时间常数与等待时间匹配），<strong>功率不超</strong>（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msubsup><mi>U</mi><mn>0</mn><mn>2</mn></msubsup><mi mathvariant="normal">/</mi><mi>R</mi></mrow><annotation encoding="application/x-tex">U_0^2/R</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4519em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2481em;"><span></span></span></span></span></span></span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 小于电阻额定功率）。在低压下 1 kΩ 够用，在高压下就必须加大电阻，然后靠延长等待时间来补偿。</p></blockquote></div><div class="tip custom-block" id="ex-bench-limit"><p class="custom-block-title">例 2 · 限流设多少</p><p><strong>题干</strong>：用一个 5 V 台式电源给一块 MCU 板供电，板上有一个 7805（输入 12 V 来自另一个电源）和一个 100 μF 的输入电容。正常工作时整板电流 60 mA，峰值 150 mA，持续 2 ms。限流应该设在多少？</p><p><strong>解</strong></p><p><strong>第 1 步：确定峰值电流的持续时间</strong></p><p>峰值 150 mA 持续 2 ms。电源的恒流模式反应时间通常是几十毫秒（由环路带宽决定），所以 2 ms 的峰值<strong>不会</strong>触发限流。</p><p><strong>第 2 步：设限流</strong></p><p>按 1.2~1.5 倍的平均电流：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>60</mn><mo>×</mo><mn>1.5</mn><mo>=</mo><mn>90</mn></mrow><annotation encoding="application/x-tex">60 \\times 1.5 = 90</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">60</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.5</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">90</span></span></span></span> mA。但这样一旦进入峰值，电压就可能被拉低，导致复位。更稳妥的是按峰值的 1.2 倍：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>150</mn><mo>×</mo><mn>1.2</mn><mo>=</mo><mn>180</mn></mrow><annotation encoding="application/x-tex">150 \\times 1.2 = 180</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">150</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">180</span></span></span></span> mA。</p><p><strong>第 3 步：考虑短路时的后果</strong></p><p>限流 180 mA，5 V 短路时功率 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>5</mn><mo>×</mo><mn>0.18</mn><mo>=</mo><mn>0.9</mn></mrow><annotation encoding="application/x-tex">5 \\times 0.18 = 0.9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.18</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.9</span></span></span></span> W，全部落在电源调整管上，随时可切断。如果设成 3 A，短路时就是 15 W，在 MCU 板的地线上，15 W 足以让细走线烧断。</p><p><strong>第 4 步：检查 7805 的功耗</strong></p><p>7805 输入 12 V、输出 5 V、电流 60 mA：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>P</mi><mo>=</mo><mo stretchy="false">(</mo><mn>12</mn><mo>−</mo><mn>5</mn><mo stretchy="false">)</mo><mo>×</mo><mn>0.06</mn><mo>=</mo><mn>0.42</mn><mtext> W</mtext></mrow><annotation encoding="application/x-tex">P = (12 - 5) \\times 0.06 = 0.42\\ \\text{W} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">12</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">5</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.06</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0.42</span><span class="mspace"> </span><span class="mord text"><span class="mord">W</span></span></span></span></span></span><p>TO-220 封装无散热片时热阻约 65 °C/W，温升 27 °C，可以接受。<strong>但注意 7805 的输入不是 5 V 电源</strong>，所以这个限流只管 MCU 板本身。</p><p><strong>结论</strong>：限流设 180~200 mA，而不是「按正常电流的 1.2 倍」的 72 mA。</p><blockquote><p><strong>为什么这么想</strong> 限流的目的是<strong>拦住短路与接反</strong>，不是<strong>限制正常瞬态</strong>。设得太紧，板子在正常工作就会被误判；设得太松，短路时烧的是板子。取「峰值电流的 1.2 倍」是在两者之间找平衡。</p></blockquote></div><h2 id="工程实例-一次「换保险丝」导致的连环故障" tabindex="-1">工程实例：一次「换保险丝」导致的连环故障 <a class="header-anchor" href="#工程实例-一次「换保险丝」导致的连环故障" aria-label="Permalink to &quot;工程实例：一次「换保险丝」导致的连环故障&quot;">​</a></h2><p>某同学在一块 12 V 供电的洞洞板上调试电机驱动，上电后保险丝熔断。他直接换了一个 3 A 的保险丝，上电后一块驱动芯片炸开，周围的走线烧焦。</p><p>排查：</p><ol><li>原始保险丝是 1 A，换成了 3 A，<strong>短路电流没有被限制</strong>；</li><li>驱动芯片的电源与地之间有一个 0.1 mm 的连锡；</li><li>1 A 保险丝熔断时，电流约 3 A 持续了几百毫秒；换成 3 A 后，短路电流受电源限流与线路电阻限制，达到 8 A 持续了更久，芯片内部键合线熔断。</li></ol><p><strong>教训</strong>：<strong>保险丝熔断是结果，不是原因。</strong> 第一个动作应该是查短路，而不是换一个更大的保险丝。</p><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><p>四个错误分别对应四条安全线：断电假设、隔离对象、漏保测试、手环接地——每条都有明确的一步修正。</p><div class="tip custom-block"><p class="custom-block-title">错误 1 · 以为「关掉开关」就安全了</p><p><strong>现象</strong>：关掉台式电源的开关，但输出电容仍然充电，接上一个低阻负载后打火。</p><p><strong>处理</strong>：关机后等 30 秒，用万用表确认输出电压为 0。台式电源的输出电容通常在几百到几千微法，关机后仍可能保持数伏。</p></div><div class="tip custom-block"><p class="custom-block-title">错误 2 · 用隔离变压器给示波器供电</p><p><strong>现象</strong>：为了「让示波器浮起来」，把示波器接在隔离变压器上，然后探头的地的确不再接大地了。</p><p><strong>处理</strong>：这是危险的。正确做法是隔离<strong>被测设备</strong>，让示波器的地保持接地。如果必须测浮地信号，用差分探头。</p></div><div class="tip custom-block"><p class="custom-block-title">错误 3 · 不按漏保测试按钮</p><p><strong>现象</strong>：以为装了漏保就安全，从未测试过。实际漏保可能已经失效（线圈烧了、机械卡死）。</p><p><strong>处理</strong>：每月按一次 Test 按钮，确认能跳闸；跳闸后用复位按钮恢复。跳闸后不要直接推上去，先查有没有漏电。</p></div><div class="tip custom-block"><p class="custom-block-title">错误 4 · 防静电手环直接接大地</p><p><strong>现象</strong>：自制手环用一根铜线直接连到暖气管或水管上。</p><p><strong>处理</strong>：手环必须通过 1 MΩ 电阻接大地。直接接大地时，手环在你接触漏电时变成了一条低阻通路，危险性反而增加。买合格的防静电手环，它内部已经有这个电阻。</p></div><h2 id="自检清单" tabindex="-1">自检清单 <a class="header-anchor" href="#自检清单" aria-label="Permalink to &quot;自检清单&quot;">​</a></h2><p>这张清单覆盖本页全部六条安全线：分区、接地、限流、保险丝、放电、防静电。每次上电前扫一遍。</p><ul><li>[ ] 桌面分强电区与弱电区，绝缘垫隔开；</li><li>[ ] 墙上插座是三孔、有有效接地，漏保测试按钮按下能跳闸；</li><li>[ ] 台式电源的限流已设置，并且知道它设在哪里；</li><li>[ ] 电池供电有保险丝，线径与电流匹配；</li><li>[ ] 大电容已放电并验证，测电压 5 V 以下；</li><li>[ ] 防静电手环与台垫已佩戴并接地；</li><li>[ ] 示波器的地线夹只夹一个点，且是真实参考地；</li><li>[ ] 桌上没有裸露的 220 V 导线，没有剪掉第三脚的插头；</li><li>[ ] 发生冒烟、异响、焦味时，第一动作是断电；</li><li>[ ] 每次改动电路后，先断电测短路，再上电。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>万用表与示波器的具体操作：<a href="./multimeter">万用表</a>、<a href="./oscilloscope">示波器</a></li><li>焊接与搭电路：<a href="./soldering">焊接与搭电路</a></li><li>强电人身安全的原理：<a href="./../ee/07-control/safety">电工学 21 · 安全用电</a></li><li>回到板块总览：<a href="./">实验与仪器</a></li></ul>',27))])}const M=o(g,[["render",x]]);export{f as __pageData,M as default};
